<script setup lang="ts">definePageMeta({ middleware:'teacher' }); const user=useSupabaseUser(); const supabase=useSupabaseClient(); const events=ref<any[]>([]); onMounted(async()=>{const{data}=await supabase.from('events').select('id,name,event_date,start_time,status,sport:sports(name)').or(`teacher_id.eq.${user.value!.id},teacher_id.is.null`).order('event_date');events.value=data||[]})</script>
<template><main class="mx-auto max-w-6xl px-4 py-8"><p class="text-sm font-bold uppercase tracking-wider text-emerald-600">Teacher</p><h1 class="mt-1 text-3xl font-bold">Event Management</h1><p class="mt-2 text-slate-500">Select an event to enter or update results.</p><div class="mt-6 grid gap-4 md:grid-cols-2"><NuxtLink v-for="e in events" :key="e.id" :to="`/teacher/events/${e.id}`" class="rounded-xl border bg-white p-5 shadow-sm hover:border-emerald-300"><div class="font-bold">{{e.name}}</div><div class="mt-1 text-sm text-slate-500">{{e.event_date}} · {{e.sport?.name}}</div><div class="mt-3 text-sm capitalize">{{e.status.replaceAll('_',' ')}}</div></NuxtLink></div></main></template>
